// Social preview image (1200x630), inlined so the worker is self-contained.
// LinkedIn, Slack, X and Google all read the OpenGraph tags in page.ts which
// point at /og.png. Regenerate with scripts/make-og.py if the wording changes.
const OG_BASE64 =
  "";

const BYTES = Uint8Array.from(atob(OG_BASE64), (c) => c.charCodeAt(0));

export function ogImageResponse(): Response {
  return new Response(BYTES, {
    headers: {
      "content-type": "image/png",
      "cache-control": "public, max-age=86400",
    },
  });
}
